#!/usr/bin/env python3
"""Materialize the temporary issue #50 integration diff for canonical patch generation."""
from __future__ import annotations

import base64
import lzma
import sys
from pathlib import Path

_PAYLOAD = ""


def main() -> int:
    if len(sys.argv) != 2:
        raise SystemExit("usage: issue50_apply.py OUTPUT")
    Path(sys.argv[1]).write_bytes(lzma.decompress(base64.b64decode(_PAYLOAD)))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
